class Solution {
public:
    int maxRepeating(string sequence, string word) {
        int limit = sequence.size() / word.size();
        string rep;
        for (int i = 0; i < limit; i++) rep += word;
        for (int k = limit; k >= 1; k--) {
            if (sequence.find(rep) != string::npos) return k;
            rep.resize(rep.size() - word.size());
        }
        return 0;
    }
};

