        StringBuilder rep = new StringBuilder();
        int limit = sequence.length() / word.length();
        for (int k = limit; k >= 1; k--) {
            rep.setLength(0);
            for (int i = 0; i < k; i++) rep.append(word);
            if (sequence.contains(rep)) return k;
        }
        return 0;
    }
}

