class Solution:
    def maximumRepeatingSubstring(self, sequence: str, word: str) -> int:
        m, n = len(sequence), len(word)
        if m < n:
            return 0
        dp = [0] * m
        best = 0
        for i in range(n - 1, m):
            if sequence[i - n + 1:i + 1] == word:
                dp[i] = (dp[i - n] if i >= n else 0) + 1
                best = max(best, dp[i])
        return best

