        if (m < n) return 0;
        vector<int> dp(m, 0);
        for (int i = n - 1; i < m; i++) {
            if (sequence.compare(i - n + 1, n, word) == 0) {
                dp[i] = (i >= n ? dp[i - n] : 0) + 1;
                best = max(best, dp[i]);
            }
        }
        return best;
    }
};

