class Solution {
    public int maxRepeating(String sequence, String word) {
        int m = sequence.length(), n = word.length(), best = 0;
        if (m < n) return 0;
        int[] dp = new int[m];
        for (int i = n - 1; i < m; i++) {
            if (sequence.startsWith(word, i - n + 1)) {
                dp[i] = (i >= n ? dp[i - n] : 0) + 1;
                best = Math.max(best, dp[i]);
            }
        }
        return best;
    }
}

